						</button>
						<button class="chat-chip btn btn-xs btn-outline rounded-full font-medium" data-prompt="Create competitive objection handling battlecards for Stripe ($280k ARR) overcoming renewal objections regarding data security.">
							🛡️ Stripe ($280k): Security Battlecards
						</button>
					</div>
				</div>

			</div>

			<!-- EXPANSIVE BOTTOM PROMPT BAR -->
			<div class="pt-3 w-full max-w-5xl xl:max-w-6xl mx-auto sticky bottom-0 z-30 bg-base-100/90 backdrop-blur-md">
				<form id="chat-form" class="card bg-base-200/80 border border-base-300 p-2 sm:p-2.5 rounded-2xl shadow-xs flex flex-row items-center gap-2">
					<input
						id="chat-input"
						type="text"
						class="input input-sm sm:input-md flex-1 bg-transparent border-0 text-xs sm:text-sm text-base-content focus:outline-none"
						placeholder="Plan a deal (e.g. 'Discovery with Snowflake for $400k ARR, prepare pitch deck and talk-tracks...')"
						autocomplete="off"
					/>
